const json = (statusCode, body) => ({
  statusCode,
  headers: {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization',
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    'Cache-Control': 'no-store',
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(body)
});
 
exports.handler = async (event) => {
  if (event.httpMethod === 'OPTIONS') return json(204, {});
  if (event.httpMethod !== 'POST') return json(405, { error: 'POST only' });
 
  const SB_URL = process.env.SUPABASE_URL;
  const SB_SERVICE = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!SB_URL || !SB_SERVICE) return json(500, { error: 'Not configured on this site.' });
 
  const token = (event.headers.authorization || '').replace(/^Bearer\s+/i, '');
  if (!token) return json(401, { error: 'Sign in first.' });
 
  // 1. Who is asking?
  let user;
  try {
    const r = await fetch(SB_URL + '/auth/v1/user', {
      headers: { apikey: SB_SERVICE, Authorization: 'Bearer ' + token }
    });
    user = await r.json();
    if (!r.ok || !user || !user.id) return json(401, { error: 'Your session has expired — sign in again.' });
  } catch (e) {
    return json(502, { error: 'Could not check your session.' });
  }
 
  // 2. Do they hold a licence? Read with the service role so the answer does
  //    not depend on anything the browser could influence.
  try {
    const r = await fetch(SB_URL + '/rest/v1/licences?select=user_id&user_id=eq.' + user.id, {
      headers: { apikey: SB_SERVICE, Authorization: 'Bearer ' + SB_SERVICE }
    });
    const rows = await r.json();
    if (!r.ok || !Array.isArray(rows) || !rows.length) {
      return json(403, { error: 'No licence on this account.' });
    }
  } catch (e) {
    return json(502, { error: 'Could not check your licence.' });
  }
 
  return json(200, { points: POINTS });
};
